) AS (
  VALUES 
    (746::BIGINT, 'No se asusten con la nota jajajaj Tiene todas las cualidades que un estudiante comprometido puede apreciar en un profesor, calidad tanto como persona y profesor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-08-26T00:00:00+00:00'::TIMESTAMPTZ, 'a8a584e9fe4e32a2a5d586bbf36fd3ade049208e2024d3549450eaa9c256ff00'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'No se asuste con la calificación, alguien evaluó con -256 y por eso tiene un 1.9 El profe es muy buena gente, a veces explica cosas que no se ven en el curso y sus clases virtuales son largas y se hacen un poco aburridas El primer examen fue un trabajo de "investigación" que no estuvo muy difícil'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas']::TEXT[], '2024-11-21T00:00:00+00:00'::TIMESTAMPTZ, '3e58e15e2a287ca63351569dceae65cc4a6bf268df5dc9b81029b892a41741ca'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Un maravilloso profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2024-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'a397a900f722747bb83dd667c978f1ab2ff82b0934a96d82fa347ec031fcd3a8'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2024-01-15T00:00:00+00:00'::TIMESTAMPTZ, '4b9cd024edd805fdbdff55a71e6317a6acdf17a228247a5e96795cc0e5d22a27'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'El hombre que yoooo aaamoo. Excelente profe, sus clases son otro nivel, nunca había tenido una clase en la que aprendiera así'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-10-03T00:00:00+00:00'::TIMESTAMPTZ, '5af847f0d28ebd6481290b968ce8f89721a435d6b622caea4e66b29855a4929f'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Te amo'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-09-13T00:00:00+00:00'::TIMESTAMPTZ, 'db248971319a6454746c17293506fe413d68a0ccff8aadfd43afd4bd00bd3f64'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Exc. Debería dar más cursos en la carrera'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-07-26T00:00:00+00:00'::TIMESTAMPTZ, 'a8e058a7f9bc8b86c10e7183bb52be3869056bda2842df8529e33eec9d52d773'::TEXT, ARRAY[3262]::BIGINT[]),
    (746::BIGINT, 'Excelente profesor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2023-05-17T00:00:00+00:00'::TIMESTAMPTZ, '525645415806d49c57f52e48c2b101af32598292b4bd3ac401abb1bfc5b2eed7'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'El curso es algo pesado en el inicio y un poco al final, sin embargo el profesor hace el curso sumamente llevadero e incluso facil, aparte es uno de los mejores profesores de la escuela y como persona tambien, matricularia sin duda de nuevo con él,'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Pocos exámenes', 'Tomaría su clase nuevamente']::TEXT[], '2022-12-17T00:00:00+00:00'::TIMESTAMPTZ, '8074fdcab06a8be3824c87d75d0a0f5b4331eda0c19a5ea12be4163249326259'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Ha sido mi curso fav hasta el momento. El profe es excelente, no entiendo porque tiene una carita triste. Sabe DEMASIADO del tema porque es su área. Más allá de memorizar busca que uno analice casos. Los exámenes no son del otro mundo, son de mucho análisis. Super recomendado 100/10 (love you Luis)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Inspirador']::TEXT[], '2022-12-12T00:00:00+00:00'::TIMESTAMPTZ, 'cdf2ef42a8ba12cc99dc1be753a7491c8745b4cd61b755b6ca0444167bfac2fc'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Es un buen profesor, enseña bien y en sus exámenes busca que uno analice y piense y no memorizar únicamente.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-08T00:00:00+00:00'::TIMESTAMPTZ, '99c592ea92771f88011583cfe43d6cc09d23337c11671e49760dab6554793b01'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2022-10-30T00:00:00+00:00'::TIMESTAMPTZ, 'c2c11207d01f9deac5fbdbb18b2baedb9d5d601bd945906a504dd7c37f279f31'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'El profe es demasiado bueno, no entiendo porque tienen comentarios tan malos, realmente se preocupa porque usted aprenda y analice, entiende al estudiante y le ayuda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-09-23T00:00:00+00:00'::TIMESTAMPTZ, 'b05e487898705b5f56f79acb09901940cb4cc094efbdd276b2f11ad9f3574cb7'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'El profe sabe demasiado, explica muy bien la materia y responde a todas las consultas. Le interesa que los estudiantes aprendan y entiendan, más allá de una calificación. Súper recomendado!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-09-07T00:00:00+00:00'::TIMESTAMPTZ, '0d647bb8537a68a7c1de5bb0fe892b27620cb879e1dc2335c455bf0af4e98850'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Este profe es un cracks sabe demasiado , pero su forma de explicar no es la mejor , nunca se queda bien , siempre hay peros y no ayuda con la retroalimentación, te hace sentir mal y no piensa lo que dice como retroalimentación No lo volvería a llevar con el'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2021-12-07T00:00:00+00:00'::TIMESTAMPTZ, '05d4f4e16272a401324d3aa62bbee8c1689fa543be6e30895c644de004eee398'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Sabe muchísimo pero explica demasiado rápido y confuso. La retroalimentación que da son comentarios destructivos y no constructivos. Cero empático.'::TEXT, 2.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2021-11-26T00:00:00+00:00'::TIMESTAMPTZ, '01d6d749aa3af68b974331176498edacc99b6ef91eb67f6c15214e5c7496c97b'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-03-25T00:00:00+00:00'::TIMESTAMPTZ, '97686ebac80209fb8ccc271d51709eb8976876dcd35540321cec02d29437c908'::TEXT, ARRAY[1979]::BIGINT[]),
    (746::BIGINT, 'Él sabe mucho, le encanta transmitirlo, procura que los estudiantes entiendan de verdad, profundicen y analicen los temas. Sí habla rápido y mucho. Es algo exigente y estricto calificando, pero da muy buena retroalimentación y apoyo. Se aprende bastante y es inspiracional.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-09T00:00:00+00:00'::TIMESTAMPTZ, 'c26fc6bb363bb92e1da1f66176448d2018c4a6e376b5e1b3b7d3dbb9b6481850'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Buen profesor. Sabe mucho y sabe como transmitirlo a los estudiantes. Habla un poco rápido y es difícil tomar nota. Le gusta que sus estudiantes aprendan a analizar y no tanto memorizar, por lo que sus exámenes son de investigar en gran parte.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, 'dbe95a0fd7bae3b81680831cf1d57a21d253eabd527863d041616c421b01e5e1'::TEXT, ARRAY[3262]::BIGINT[]),
    (746::BIGINT, '[Virtual] el profe es pura vida, sin embago a la hora de explicar habla tanto y tan rápido que cuenta agarrar lo que el dice. Le gusta que participen clase y deja trabajos grupales. Los examenes son mucho de investigar y analizar.'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo']::TEXT[], '2021-02-01T00:00:00+00:00'::TIMESTAMPTZ, '5e63180c77a6972b206b3e37ae30cb0fd881c52bef2aa5a56f4b98d3c680daa0'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2020-02-17T00:00:00+00:00'::TIMESTAMPTZ, '2f517061c0a28190d62cf96329a30c80616dafe6382d07101c84a94cbbb0ff72'::TEXT, ARRAY[1979]::BIGINT[]),
    (746::BIGINT, 'Es súper buen profesor, se interesa mucho por el estudiante, lo más importante es que uno aprenda y no tanto la nota. Hace quices de mucho analizar, pero te ayuda para el examen. Ayuda mucho y es comprensible. Amé como explicaba la materia súper claro y fácil.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-12-11T00:00:00+00:00'::TIMESTAMPTZ, '5b084c612ad0d6bb03133db39f7d067a24eaf32e1684bc155e926b7d46061552'::TEXT, ARRAY[1979]::BIGINT[]),
    (746::BIGINT, 'Excelente profesor y calidad de persona'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'e225db77ea8db3bef45547b379106a61bec2918d94da618396d646e39f9f7fc9'::TEXT, ARRAY[3261, 1976]::BIGINT[]),
    (746::BIGINT, 'Es muy bueno, es super claro, justo y lo hace analizar las cosas, no solo memorizar'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes']::TEXT[], '2019-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'a2d78c5bd75d8362c51ff61181a803cec121547044c6a4c893548fdc8cf738dd'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Es de los mejores profes, hace que los estudiantes se enamoren del curso, entiende mucho a los estudiantes, explica a profundidad los temas, excelente persona'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-09-18T00:00:00+00:00'::TIMESTAMPTZ, '2d2d63868070c1fa27df170bfd5ccf9a6500864df347d1bda83d60d5c03b6a74'::TEXT, ARRAY[3261]::BIGINT[]),
    (746::BIGINT, 'Es una excelente persona como profesor. En las clases el profe se extiende para explicar más profundo los procesos que se llevan a cabo en el lab, lo cual hace super interesante la clase. Prepararse bien para los quices puesto que son rudos justo como el exámen. Matricule con el y pasa de fijo.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-07-22T00:00:00+00:00'::TIMESTAMPTZ, '1cb6cc769cd2795da88a643491216cebe4efacc94a12d92ab80a605702f3ac81'::TEXT, ARRAY[1979]::BIGINT[]),
    (746::BIGINT, 'Clase llevadera, sabe que lo más importante es aprender y no una nota. Es flexible y entiende bien al estudiante'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-11T00:00:00+00:00'::TIMESTAMPTZ, '8837b5f0c06aba52d375aeb832940c326f6bf70da7e2596f04fb41394599b983'::TEXT, ARRAY[1976]::BIGINT[]),
    (746::BIGINT, 'Es claro y muy practico, entiende al estudiante y se enfoca en lo mas importante para el futuro. Lo recomiendo mucho'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2019-06-08T00:00:00+00:00'::TIMESTAMPTZ, '81f5882cdba0cacd91e555dab7c0e4d7eefc71871453c37e9fe032e6bca88504'::TEXT, ARRAY[1976]::BIGINT[]),
    (746::BIGINT, 'Excelente profesor. Explica lo más importante, atiende dudas. Le importa más que usted entienda la clase y no que la memorice. Aprendí mucho con él, sabe demasiado y es buena persona.Uno de los mejores profes para el curso :D'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-12-11T00:00:00+00:00'::TIMESTAMPTZ, '1568d8b1a844a411b170f38ba507ccdefbd1db1c813d034366c62d638e5be625'::TEXT, ARRAY[3261, 1976]::BIGINT[]),
    (746::BIGINT, 'Es el mejor profe, ayuda mucho y es super chill para calificar. Se entiende muy bien. Si no sabe algo lo investiga. Hace la clase muy divertida y llevadera.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2018-12-04T00:00:00+00:00'::TIMESTAMPTZ, '8f9d4f383a94a728f9b538b5169cbc6fb748f54275483389666830ed772b687f'::TEXT, ARRAY[3262]::BIGINT[]),
    (746::BIGINT, 'Increiblemente bueno. La materia queda super clara con su explicaion. Siempre mantiene su lema "lo importante es aprender y no las calificaciones" Cualquier consulta, no duden en hacersela.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-08T00:00:00+00:00'::TIMESTAMPTZ, '48831d7655944868ad4b404134886f06e0bddb9daff0877a1c6c06a027f826ed'::TEXT, ARRAY[1976]::BIGINT[]),
    (746::BIGINT, 'Excelente, hay que ponerle. Si alguien no le cae bien no lo para de molestar hasta que aprenda. Explica increíble y está dispuesto a ayudar!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'f9742cfd426fe81acfd77376b3aaa34b7f8ba99d191dca46514dd0fbbd30a87b'::TEXT, ARRAY[3262]::BIGINT[]),
    (746::BIGINT, 'Excelente profesor, explica super bien la materia y en caso de dudas está más que dispuesto a ayudar. El profe Luis Fernando deja sus blancos al aire.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'cb4ebfad363d92e3d86350488e15bb773333d710474ccb0def1789a650676961'::TEXT, ARRAY[3262]::BIGINT[]),
    (746::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2016-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'f7d004d152a1185c94868b1f715e08a5b0d1c07876faed2ef6be30c962f82510'::TEXT, ARRAY[3262]::BIGINT[]),
    (746::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Exámenes retadores']::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'a40bf97566d7a519bc1fbd5414f7752b80671e8e69e7d60ba025961efa7a4d7a'::TEXT, ARRAY[3262]::BIGINT[]),
    (746::BIGINT, 'Es un crack! Domina mucho la materia y ayuda mucho si se tiene alguna duda. Si se puede matricular con él,no lo dude'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-03T00:00:00+00:00'::TIMESTAMPTZ, '55bf73ac886688e91c6d86ad21a18de5b9dc98d4b032e77f3d18ca63d39e2bcf'::TEXT, ARRAY[1979]::BIGINT[]),
    (746::BIGINT, 'Excelente profesor, explica super bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-17T00:00:00+00:00'::TIMESTAMPTZ, '1db58660ae6fc69fdc359917caad27f109532da4afad64effa442ebe81a5750d'::TEXT, ARRAY[1976]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
